/**
 * Directed "blocked by" links. Every query is scoped by `orgId`.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { and, asc, eq, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

export async function insertDependency(input: {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
  createdBy: UserId;
}): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId: input.orgId,
      issueId: input.issueId,
      blockerId: input.blockerId,
      createdBy: input.createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();
  return toIssueDependency(row);
}

/** Resolves `true` when a row was deleted and `false` when there was none. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const existing = await findDependency(orgId, issueId, blockerId);
  if (!existing) return false;

  getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .run();
  return true;
}

/** Every directed link in the organization, for cycle detection. */
export async function listEdges(
  orgId: OrgId,
): Promise<readonly { issueId: IssueId; blockerId: IssueId }[]> {
  const rows = getDb()
    .select({
      issueId: issueDependencies.issueId,
      blockerId: issueDependencies.blockerId,
    })
    .from(issueDependencies)
    .where(orgPredicate(issueDependencies.orgId, orgId))
    .all();

  return rows.map((row) => ({
    issueId: row.issueId as IssueId,
    blockerId: row.blockerId as IssueId,
  }));
}

/**
 * Blockers of `issueId` that are not archived, open or closed, ordered by
 * issue number ascending.
 */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return listLinkedIssues(orgId, issueId, "blockers", {
    liveOnly: true,
    openOnly: false,
  });
}

/** Blockers that are still open: not archived, and neither done nor canceled. */
export async function listOpenBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return listLinkedIssues(orgId, issueId, "blockers", {
    liveOnly: true,
    openOnly: true,
  });
}

/** Issues that list `blockerId` as a blocker, including archived and closed. */
export async function listDependentIssues(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  return listLinkedIssues(orgId, blockerId, "dependents", {
    liveOnly: false,
    openOnly: false,
  });
}

function linkedIds(
  orgId: OrgId,
  id: IssueId,
  direction: "blockers" | "dependents",
) {
  const match =
    direction === "blockers"
      ? eq(issueDependencies.issueId, id)
      : eq(issueDependencies.blockerId, id);
  const selected =
    direction === "blockers"
      ? issueDependencies.blockerId
      : issueDependencies.issueId;

  return getDb()
    .select({ id: selected })
    .from(issueDependencies)
    .where(and(orgPredicate(issueDependencies.orgId, orgId), match));
}

async function listLinkedIssues(
  orgId: OrgId,
  id: IssueId,
  direction: "blockers" | "dependents",
  scope: { liveOnly: boolean; openOnly: boolean },
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          scope.liveOnly ? livePredicate(issues.archivedAt, {}) : undefined,
          scope.openOnly
            ? notInArray(issues.status, [...CLOSED_ISSUE_STATUSES])
            : undefined,
          inArray(issues.id, linkedIds(orgId, id, direction)),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/**
 * Blocked-by links: record them, refuse cycles, and tell an assignee when their issue is finally unblocked.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { notify } from "./notification-service";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised when an issue is marked done while an open blocker remains. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;
  readonly blockerIds: readonly IssueId[];

  constructor(blockerIds: readonly IssueId[]) {
    super("Issue cannot be marked done while it has open blockers");
    this.name = "IssueBlockedError";
    this.blockerIds = blockerIds;
  }
}

export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  const edges = await dependencyRepo.listEdges(input.orgId);
  if (wouldCreateCycle(edges, input.issueId, input.blockerId)) {
    throw new Error(
      `Linking ${input.issueId} to blocker ${input.blockerId} would create a cycle`,
    );
  }

  return dependencyRepo.insertDependency({
    orgId: input.orgId,
