import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { notify } from "./notification-service";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised when an issue is marked done while an open blocker remains. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;
  readonly blockerIds: readonly IssueId[];

  constructor(blockerIds: readonly IssueId[]) {
    super("Issue cannot be marked done while it has open blockers");
    this.name = "IssueBlockedError";
    this.blockerIds = blockerIds;
  }
}

export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  const edges = await dependencyRepo.listEdges(input.orgId);
  if (wouldCreateCycle(edges, input.issueId, input.blockerId)) {
    throw new Error(
      `Linking ${input.issueId} to blocker ${input.blockerId} would create a cycle`,
    );
  }

  return dependencyRepo.insertDependency({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
  });
}

export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issueId);
}

/**
 * Attaches the unblock fan-out. Called from `registerEventHandlers` so a
 * status change or archive has already delivered the notification when the
 * service call resolves.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", (payload) =>
      onBlockerStatusChanged(payload),
    ),
    subscribe("issue.archived", (payload) => onBlockerArchived(payload)),
  ];
  return () => {
    for (const off of offs) off();
  };
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * A new edge `issueId -> blockerId` ("issueId is blocked by blockerId") cycles
 * when `blockerId` already reaches `issueId`, including the self-link.
 */
function wouldCreateCycle(
  edges: readonly { issueId: IssueId; blockerId: IssueId }[],
  issueId: IssueId,
  blockerId: IssueId,
): boolean {
  if (issueId === blockerId) return true;

  const blockedBy = new Map<string, string[]>();
  for (const edge of edges) {
    const next = blockedBy.get(edge.issueId) ?? [];
    next.push(edge.blockerId);
    blockedBy.set(edge.issueId, next);
  }

  const seen = new Set<string>();
  const stack = [blockerId as string];
  while (stack.length > 0) {
    const current = stack.pop();
    if (current === undefined || seen.has(current)) continue;
    if (current === issueId) return true;
    seen.add(current);
    for (const next of blockedBy.get(current) ?? []) stack.push(next);
  }
  return false;
}

async function onBlockerStatusChanged(payload: {
  orgId: OrgId;
  actorId: UserId | null;
  issueId: IssueId;
  from: IssueStatus;
  to: IssueStatus;
}): Promise<void> {
  const becameClosed = !isClosedStatus(payload.from) && isClosedStatus(payload.to);
  if (!becameClosed) return;
  await notifyUnblockedDependents(payload.orgId, payload.issueId, payload.actorId);
}

async function onBlockerArchived(payload: {
  orgId: OrgId;
  actorId: UserId | null;
  issueId: IssueId;
}): Promise<void> {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  if (!issue || isClosedStatus(issue.status)) return;
  await notifyUnblockedDependents(payload.orgId, payload.issueId, payload.actorId);
}

async function notifyUnblockedDependents(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const dependents = await dependencyRepo.listDependentIssues(orgId, blockerId);

  for (const issue of dependents) {
    if (issue.archivedAt !== null) continue;
    if (isClosedStatus(issue.status)) continue;
    if (issue.assigneeId === null) continue;

    const openBlockers = await dependencyRepo.listOpenBlockers(orgId, issue.id);
    if (openBlockers.length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "Issue unblocked",
      body: `"${issue.title}" is no longer blocked`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}
