import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { updateNotificationPreferenceSchema } from "@/schemas/notification";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  IssueBlockedError,
  addBlocker,
  listBlockers,
  removeBlocker,
} from "@/server/services/issue-dependency-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import type { IssueId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("deps");
  other = await createTenant("deps-other");
});

afterAll(() => {
  cleanup();
});

async function makeIssue(
  title: string,
  assigneeId: UserId | null = null,
): Promise<Issue> {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title, assigneeId }),
  );
}

async function unblockedFor(recipientId: UserId, issueId: IssueId) {
  const page = await notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    limit: 50,
    cursor: null,
    kind: ["issue_unblocked"],
  });
  return page.items.filter((row) => row.href === `/issues/${issueId}`);
}

describe("issue dependencies", () => {
  it("accepts issue_unblocked in the preference schema", () => {
    const parsed = updateNotificationPreferenceSchema.parse({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      kind: "issue_unblocked",
      inApp: false,
      email: true,
      digestOnly: false,
    });
    expect(parsed.kind).toBe("issue_unblocked");
  });

  it("records a link, returns the same row when added twice, and lists by number", async () => {
    const low = await makeIssue("low");
    const high = await makeIssue("high");
    const blocked = await makeIssue("blocked");

    const first = await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: high.id,
    });
    const again = await addBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: high.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: low.id,
    });

    expect(again).toEqual(first);
    expect(first.createdBy).toBe(tenant.userIds.member);
    const listed = await listBlockers(tenant.actors.viewer, tenant.org.id, blocked.id);
    expect(listed.map((issue) => issue.id)).toEqual([low.id, high.id]);
    expect(await dependencyRepo.listEdges(tenant.org.id)).toHaveLength(2);
  });

  it("rejects self links, cycles, missing issues, other tenants, viewers, and archived issues", async () => {
    const a = await makeIssue("a");
    const b = await makeIssue("b");
    const c = await makeIssue("c");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: a.id,
      blockerId: b.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: b.id,
      blockerId: c.id,
    });

    const before = await dependencyRepo.listEdges(tenant.org.id);

    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: a.id,
        blockerId: a.id,
      }),
    ).rejects.toThrow(Error);
    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: c.id,
        blockerId: a.id,
      }),
    ).rejects.toThrow(Error);
    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: a.id,
        blockerId: "01ARZ3NDEKTSV4RRFFQ69G5FAV" as IssueId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      addBlocker(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: a.id,
        blockerId: b.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      addBlocker(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: a.id,
        blockerId: c.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, c.id);
    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: a.id,
        blockerId: c.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(await dependencyRepo.listEdges(tenant.org.id)).toEqual(before);
  });

  it("removes a link only when the blocked issue exists and the actor may edit it", async () => {
    const blocked = await makeIssue("removable");
    const blocker = await makeIssue("remover");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });

    expect(
      await removeBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: "01ARZ3NDEKTSV4RRFFQ69G5FAV" as IssueId,
      }),
    ).toBe(false);

    await expect(
      removeBlocker(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: blocker.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect(
      await removeBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: blocker.id,
      }),
    ).toBe(true);
    expect(
      await removeBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: blocker.id,
      }),
    ).toBe(false);

    await expect(
      removeBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: "01ARZ3NDEKTSV4RRFFQ69G5FAV" as IssueId,
        blockerId: blocker.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses marking done while an open blocker remains, including a board move", async () => {
    const blocker = await makeIssue("gate-blocker");
    const blocked = await makeIssue("gate-blocked");
    const closed = await makeIssue("gate-closed");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: closed.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: closed.id,
      status: "canceled",
    });

    const seen: unknown[] = [];
    const off = subscribe("issue.status_changed", (payload) => {
      if (payload.issueId === blocked.id) seen.push(payload);
    });

    try {
      const error = await issueService
        .changeIssueStatus(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: blocked.id,
          status: "done",
        })
        .catch((caught: unknown) => caught);

      expect(error).toBeInstanceOf(IssueBlockedError);
      expect((error as IssueBlockedError).code).toBe("conflict");
      expect((error as IssueBlockedError).blockerIds).toEqual([blocker.id]);

      await expect(
        issueService.moveIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: blocked.id,
          toStatus: "done",
          toIndex: 0,
        }),
      ).rejects.toBeInstanceOf(IssueBlockedError);

      const fresh = await issueService.getIssue(
        tenant.actors.member,
        tenant.org.id,
        blocked.id,
      );
      expect(fresh.issue.status).toBe("backlog");
      expect(seen).toHaveLength(0);

      const moved = await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        status: "in_progress",
      });
      expect(moved.status).toBe("in_progress");
    } finally {
      off();
    }
  });

  it("notifies the assignee once when the last open blocker closes or is archived", async () => {
    const assignee = tenant.userIds.admin;
    const blocker = await makeIssue("notify-blocker");
    const otherBlocker = await makeIssue("notify-other");
    const blocked = await makeIssue("notify-blocked", assignee);
    const second = await makeIssue("notify-second", assignee);
    const unassigned = await makeIssue("notify-unassigned", null);
    const doneDependent = await makeIssue("notify-done", assignee);

    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: otherBlocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      blockerId: blocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: unassigned.id,
      blockerId: blocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doneDependent.id,
      blockerId: blocker.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doneDependent.id,
      status: "canceled",
    });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "done",
    });

    expect(await unblockedFor(assignee, blocked.id)).toHaveLength(0);
    expect(await unblockedFor(assignee, second.id)).toHaveLength(1);
    expect(await unblockedFor(assignee, unassigned.id)).toHaveLength(0);
    expect(await unblockedFor(assignee, doneDependent.id)).toHaveLength(0);

    const note = (await unblockedFor(assignee, second.id))[0];
    expect(note?.kind).toBe("issue_unblocked");
    expect(note?.href).toBe(`/issues/${second.id}`);
    expect(note?.actorId).toBe(tenant.userIds.member);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "canceled",
    });
    expect(await unblockedFor(assignee, second.id)).toHaveLength(1);

    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: otherBlocker.id,
      status: "done",
    });
    const cleared = await unblockedFor(assignee, blocked.id);
    expect(cleared).toHaveLength(1);
    expect(cleared[0]?.actorId).toBe(tenant.userIds.admin);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "done",
    });
    expect(await unblockedFor(assignee, second.id)).toHaveLength(2);

    const archivedBlocker = await makeIssue("archive-blocker");
    const archivedDependent = await makeIssue("archive-dependent", assignee);
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: archivedDependent.id,
      blockerId: archivedBlocker.id,
    });
    await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      archivedBlocker.id,
    );
    const archivedNote = await unblockedFor(assignee, archivedDependent.id);
    expect(archivedNote).toHaveLength(1);
    expect(archivedNote[0]?.actorId).toBe(tenant.userIds.member);

    const closedBlocker = await makeIssue("already-closed");
    const stillBlocked = await makeIssue("still", assignee);
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: stillBlocked.id,
      blockerId: closedBlocker.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: closedBlocker.id,
      status: "canceled",
    });
    expect(await unblockedFor(assignee, stillBlocked.id)).toHaveLength(1);
    await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      closedBlocker.id,
    );
    expect(await unblockedFor(assignee, stillBlocked.id)).toHaveLength(1);

    const ownBlocker = await makeIssue("own-blocker");
    const ownIssue = await makeIssue("own-issue", tenant.userIds.member);
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: ownIssue.id,
      blockerId: ownBlocker.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: ownBlocker.id,
      status: "done",
    });
    expect(await unblockedFor(tenant.userIds.member, ownIssue.id)).toHaveLength(0);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: assignee,
      kind: "issue_unblocked",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    const mutedBlocker = await makeIssue("muted-blocker");
    const mutedIssue = await makeIssue("muted-issue", assignee);
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: mutedIssue.id,
      blockerId: mutedBlocker.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: mutedBlocker.id,
      status: "done",
    });
    expect(await unblockedFor(assignee, mutedIssue.id)).toHaveLength(0);

    const linkBlocker = await makeIssue("link-blocker");
    const linkIssue = await makeIssue("link-issue", assignee);
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: linkIssue.id,
      blockerId: linkBlocker.id,
    });
    await removeBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: linkIssue.id,
      blockerId: linkBlocker.id,
    });
    expect(await unblockedFor(assignee, linkIssue.id)).toHaveLength(0);
  });

  it("allows done once every blocker is closed and keeps closed blockers in the list", async () => {
    const blocker = await makeIssue("final-blocker");
    const blocked = await makeIssue("final-blocked");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocker.id,
      status: "done",
    });
    const done = await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      status: "done",
    });
    expect(done.status).toBe("done");
    const listed = await listBlockers(tenant.actors.viewer, tenant.org.id, blocked.id);
    expect(listed.map((issue) => issue.id)).toEqual([blocker.id]);
  });
});

