      issueId: blocked.id,
      status: "done",
    });
    expect(done.status).toBe("done");
    const listed = await listBlockers(tenant.actors.viewer, tenant.org.id, blocked.id);
    expect(listed.map((issue) => issue.id)).toEqual([blocker.id]);
